sql:
SELECT SUM(`amount_usd`) AS revenue_last_12_months
FROM `workspace`.`sales2`.`orders`
WHERE `order_date` BETWEEN DATE_SUB(CURRENT_DATE, 364) AND CURRENT_DATE AND `amount_usd` IS NOT NULL AND `order_date` IS NOT NULL;

SELECT 100 * TRY_DIVIDE(
  SUM(CASE WHEN `product_line` ILIKE '%subscription%' THEN `amount_usd` ELSE 0 END),
  SUM(`amount_usd`)
) AS recurring_revenue_share_percent
FROM `workspace`.`sales2`.`orders`
WHERE `order_date` BETWEEN DATE_SUB(CURRENT_DATE, 364) AND CURRENT_DATE AND `amount_usd` IS NOT NULL AND `product_line` IS NOT NULL;
